mapper.select:
SELECT p.server_id, p.interval_hr, p.sections, p.next_dt, p.last_req_dt, p.upd_user, p.upd_dt
  FROM tb_report_policy p
 WHERE p.server_id = #{serverId}

mapper.update:
UPDATE tb_report_policy
   SET next_dt     = #{nextDt},
       last_req_dt = #{lastReqDt, jdbcType=TIMESTAMP}
 WHERE server_id = #{serverId}
   AND next_dt   = #{prevDt}

UPDATE tb_server_report
   SET status_cd = #{statusCd},
       done_dt   = CURRENT_TIMESTAMP,
       warn_cnt  = #{warnCnt},
       byte_cnt  = #{byteCnt},
       content   = #{content, jdbcType=VARCHAR}
 WHERE report_id = #{reportId}
   AND server_id = #{serverId}
   AND status_cd IN ('REQUESTED', 'SENT')

choose.when:
SELECT r.report_id
  FROM tb_server_report r
 WHERE r.server_id = #{serverId}
   AND (SELECT COUNT(*) FROM tb_server_report m
         WHERE m.server_id = r.server_id
           AND (m.req_dt > r.req_dt OR (m.req_dt = r.req_dt AND m.report_id > r.report_id))) >= #{keep}

choose.otherwise:
SELECT x.report_id
  FROM (
        SELECT r.report_id,
               ROW_NUMBER() OVER (ORDER BY r.req_dt DESC, r.report_id DESC) AS rn
          FROM tb_server_report r
         WHERE r.server_id = #{serverId}
       ) x
 WHERE x.rn > #{keep}

mapper.delete:
DELETE FROM tb_server_report
 WHERE report_id IN
#{id}

mapper.select:
SELECT m.cpu_pct, m.mem_pct, m.disk_pct, m.session_cnt, m.collect_dt AS dt
  FROM tb_server_metric m
 WHERE m.server_id = #{serverId}

SELECT MAX(h.cpu_pct) AS cpu_pct, MAX(h.mem_pct) AS mem_pct, MAX(h.disk_pct) AS disk_pct,
       MAX(h.session_cnt) AS session_cnt, COUNT(*) AS cnt
  FROM tb_server_metric_hist h
 WHERE h.server_id = #{serverId}
   AND h.collect_dt >= #{since}

SELECT a.alarm_type AS item_nm, a.alarm_level AS level_cd, a.message AS msg, a.state_cd, a.occur_dt AS dt, a.close_dt AS end_dt
  FROM tb_alarm a
 WHERE a.server_id = #{serverId}
   AND a.occur_dt >= #{since}
 ORDER BY a.occur_dt DESC, a.alarm_id DESC

SELECT c.target AS item_nm, c.cmd_cd, c.state_cd, c.req_user AS user_nm, c.req_dt AS dt, c.end_dt, c.exit_cd, c.result_msg AS msg
  FROM tb_service_cmd c
 WHERE c.server_id = #{serverId}
   AND c.req_dt >= #{since}
 ORDER BY c.req_dt DESC, c.cmd_id DESC
